#include "pal_tcp.h"

#include <string.h>
#include "lwip/sockets.h"
#include "lwip/netdb.h"
#include "esp_log.h"

static const char *TAG = "pal_tcp";

pal_tcp_socket_t pal_tcp_connect(const char *host, uint16_t port, uint32_t timeout_ms) {
    if (!host) return PAL_TCP_INVALID_SOCKET;

    struct addrinfo hints = {0}, *res = NULL;
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    char port_str[8];
    snprintf(port_str, sizeof(port_str), "%u", port);

    if (getaddrinfo(host, port_str, &hints, &res) != 0 || !res) {
        ESP_LOGE(TAG, "DNS resolution failed for %s", host);
        return PAL_TCP_INVALID_SOCKET;
    }

    int sock = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (sock < 0) {
        freeaddrinfo(res);
        return PAL_TCP_INVALID_SOCKET;
    }

    if (timeout_ms > 0) {
        struct timeval tv;
        tv.tv_sec = timeout_ms / 1000;
        tv.tv_usec = (timeout_ms % 1000) * 1000;
        setsockopt(sock, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv));
        setsockopt(sock, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
    }

    if (connect(sock, res->ai_addr, res->ai_addrlen) != 0) {
        ESP_LOGE(TAG, "Connect to %s:%u failed: errno %d", host, port, errno);
        close(sock);
        freeaddrinfo(res);
        return PAL_TCP_INVALID_SOCKET;
    }

    freeaddrinfo(res);
    ESP_LOGI(TAG, "Connected to %s:%u (sock=%d)", host, port, sock);
    return (pal_tcp_socket_t)sock;
}

int pal_tcp_send(pal_tcp_socket_t sock, const void *data, size_t len) {
    if (sock == PAL_TCP_INVALID_SOCKET || !data) return -1;
    int sent = send(sock, data, len, 0);
    if (sent < 0) {
        ESP_LOGE(TAG, "Send failed: errno %d", errno);
    }
    return sent;
}

int pal_tcp_recv(pal_tcp_socket_t sock, void *buf, size_t buf_len, uint32_t timeout_ms) {
    if (sock == PAL_TCP_INVALID_SOCKET || !buf) return -1;

    if (timeout_ms > 0 && timeout_ms != UINT32_MAX) {
        struct timeval tv;
        tv.tv_sec = timeout_ms / 1000;
        tv.tv_usec = (timeout_ms % 1000) * 1000;
        setsockopt(sock, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
    }

    int n = recv(sock, buf, buf_len, 0);
    if (n < 0) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) return 0;
        return -1;
    }
    return n;
}

void pal_tcp_close(pal_tcp_socket_t sock) {
    if (sock != PAL_TCP_INVALID_SOCKET) {
        shutdown(sock, SHUT_RDWR);
        close(sock);
    }
}

bool pal_tcp_is_connected(pal_tcp_socket_t sock) {
    if (sock == PAL_TCP_INVALID_SOCKET) return false;
    int error = 0;
    socklen_t len = sizeof(error);
    if (getsockopt(sock, SOL_SOCKET, SO_ERROR, &error, &len) != 0) return false;
    return error == 0;
}

pal_tcp_socket_t pal_tcp_listen(uint16_t port, int backlog) {
    int sock = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    if (sock < 0) return PAL_TCP_INVALID_SOCKET;

    int opt = 1;
    setsockopt(sock, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    addr.sin_addr.s_addr = INADDR_ANY;

    if (bind(sock, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        close(sock);
        return PAL_TCP_INVALID_SOCKET;
    }

    if (listen(sock, backlog > 0 ? backlog : 4) < 0) {
        close(sock);
        return PAL_TCP_INVALID_SOCKET;
    }

    ESP_LOGI(TAG, "Listening on port %u", port);
    return (pal_tcp_socket_t)sock;
}

pal_tcp_socket_t pal_tcp_accept(pal_tcp_socket_t server_sock, uint32_t timeout_ms) {
    if (server_sock == PAL_TCP_INVALID_SOCKET) return PAL_TCP_INVALID_SOCKET;

    if (timeout_ms > 0 && timeout_ms != UINT32_MAX) {
        struct timeval tv;
        tv.tv_sec = timeout_ms / 1000;
        tv.tv_usec = (timeout_ms % 1000) * 1000;
        setsockopt(server_sock, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
    }

    struct sockaddr_in client_addr;
    socklen_t addr_len = sizeof(client_addr);
    int client = accept(server_sock, (struct sockaddr *)&client_addr, &addr_len);
    if (client < 0) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) return PAL_TCP_INVALID_SOCKET;
        return PAL_TCP_INVALID_SOCKET;
    }
    return (pal_tcp_socket_t)client;
}